mapper.select:
SELECT v.id, v.store_id, s.name AS store_name, v.platform, v.seller_sku, v.platform_item_id, v.rating, v.title, v.content,
       v.review_date, v.replied, v.handle_status
FROM ecom_review v
JOIN ecom_store s ON s.id = v.store_id
WHERE v.review_date >= #{begin} AND v.review_date <= #{end}
AND v.rating <= #{maxRating}

AND (v.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR v.platform_item_id = #{keyword})
ORDER BY v.review_date DESC, v.id DESC
LIMIT #{limit}

SELECT
    (SELECT COUNT(*) FROM ecom_order o WHERE o.status <> 'CANCELLED' AND o.local_status = 'PENDING'
        ) AS "orderPending",
    (SELECT COUNT(*) FROM ecom_order o WHERE o.status <> 'CANCELLED' AND o.local_status IN ('EXCEPTION', 'ON_HOLD', 'OUT_OF_STOCK')
        ) AS "orderException",
    (SELECT COUNT(*) FROM ecom_order o WHERE o.status <> 'CANCELLED' AND o.ship_by < #{now} AND o.local_status IN 
        ) AS "orderOverdue",
    (SELECT COUNT(*) FROM ecom_return r WHERE r.status = 'PENDING'
        ) AS "returnPending",
    (SELECT COUNT(*) FROM ecom_review v WHERE v.handle_status = 'PENDING'
        ) AS "reviewPending",
    (SELECT COUNT(*) FROM ecom_fba_claim c WHERE c.status = 'PENDING' AND c.deadline IS NOT NULL AND c.deadline <= #{claimDeadline}
        ) AS "claimExpiring"

SELECT o.id, o.store_id, s.name AS store_name, o.platform_order_no, o.order_time, o.ship_by, o.local_status, o.fulfillment, o.exception, o.total_amount, o.currency FROM ecom_order o JOIN ecom_store s ON s.id = o.store_id WHERE o.status <> 'CANCELLED'
AND o.local_status IN ('EXCEPTION', 'ON_HOLD', 'OUT_OF_STOCK') AND o.ship_by < #{now} AND o.local_status IN AND o.ship_by >= #{now} AND o.ship_by < #{dueBefore} AND o.local_status IN
ORDER BY o.ship_by, o.order_time LIMIT #{limit}

SELECT t.search_term, SUM(t.impressions) AS impressions, SUM(t.clicks) AS clicks, SUM(t.orders) AS orders, SUM(t.spend) AS spend, SUM(t.sales) AS sales FROM ecom_ad_search_term t WHERE t.stat_date >= #{begin} AND (t.ad_group_id IN (SELECT d.ad_group_id AND d.ad_group_id IS NOT NULL) OR t.campaign_id IN (SELECT d.campaign_id AND d.ad_group_id IS NULL AND d.campaign_id IS NOT NULL))
AND t.store_id IN (SELECT s.id FROM ecom_store s WHERE s.marketplace = #{marketplace})
GROUP BY t.search_term HAVING SUM(t.orders) > 0 ORDER BY SUM(t.orders) DESC, SUM(t.clicks) LIMIT #{limit}
